package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.widget.*;
import org.json.JSONObject;
final class ProfileEditorDialog {
 ProfileEditorDialog(Context c,JSONObject profile,Runnable saved){NativeSheet sheet=new NativeSheet(c,"Editar perfil");LinearLayout body=sheet.body;LinearLayout identity=new LinearLayout(c);identity.setGravity(android.view.Gravity.CENTER_VERTICAL);ImageView avatar=new ImageView(c);avatar.setImageResource(R.drawable.app_logo);avatar.setScaleType(ImageView.ScaleType.CENTER_CROP);avatar.setBackground(AppStyle.shape(avatar,0xff2a3142,40));avatar.setClipToOutline(true);identity.addView(avatar,new LinearLayout.LayoutParams(NativeSheet.dp(c,64),NativeSheet.dp(c,64)));AccountImageLoader.load(avatar,profile.optString("avatar_url",""));TextView info=NativeSheet.text(c,"  Sua identidade na BatCaverna",14,0xffb7a6ff);identity.addView(info,new LinearLayout.LayoutParams(0,-2,1));body.addView(identity);
  LinearLayout tabs=new LinearLayout(c);body.addView(tabs);LinearLayout infoPanel=new LinearLayout(c);infoPanel.setOrientation(LinearLayout.VERTICAL);LinearLayout appearance=new LinearLayout(c);appearance.setOrientation(LinearLayout.VERTICAL);body.addView(infoPanel);body.addView(appearance);appearance.setVisibility(android.view.View.GONE);
  String[] labels={"Informações","Aparência","Destaques"};for(int i=0;i<3;i++){final int tab=i;Button b=new Button(c);b.setText(labels[i]);AppStyle.button(b,false);tabs.addView(b,new LinearLayout.LayoutParams(0,-2,1));b.setOnClickListener(v->{if(tab==2){HighlightsDialog.show(c,profile,saved);return;}infoPanel.setVisibility(tab==0?android.view.View.VISIBLE:android.view.View.GONE);appearance.setVisibility(tab==1?android.view.View.VISIBLE:android.view.View.GONE);});}
  for(String field:new String[]{"avatar_url","banner_url","fundo"}){Button pick=new Button(c);pick.setText(field.equals("avatar_url")?"Trocar foto":field.equals("banner_url")?"Trocar capa":"Trocar fundo");AppStyle.button(pick,false);appearance.addView(pick);pick.setOnClickListener(v->{if(c instanceof MainActivity)((MainActivity)c).chooseImage(field);});}

  Button position=new Button(c);position.setText("Posição e zoom da capa");AppStyle.button(position,false);appearance.addView(position);position.setOnClickListener(v->CoverEditorDialog.show(c,profile,saved));
  infoPanel.addView(NativeSheet.text(c,"Nome público",12,0xffa99bc7));EditText name=NativeSheet.input(c,"Nome",40);name.setSingleLine(true);name.setText(profile.optString("nome",""));infoPanel.addView(name);infoPanel.addView(NativeSheet.text(c,"Sobre você",12,0xffa99bc7));EditText bio=NativeSheet.input(c,"Biografia",280);bio.setMinLines(3);bio.setGravity(android.view.Gravity.TOP);bio.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);bio.setText(profile.isNull("bio")?"":profile.optString("bio",""));infoPanel.addView(bio);infoPanel.addView(NativeSheet.text(c,"Status do perfil",12,0xffa99bc7));final int[] selectedStatus={ProfileStatus.index(profile.optString("status_personalizado","online"))};LinearLayout status=new LinearLayout(c);status.setOrientation(LinearLayout.VERTICAL);Button[] statusButtons=new Button[ProfileInput.STATUS.length];Runnable paint=()->{for(int i=0;i<statusButtons.length;i++){Button option=statusButtons[i];boolean chosen=i==selectedStatus[0];option.setText(ProfileStatus.LABELS[i]+(chosen?"  ✓":""));option.setTextColor(ProfileStatus.COLORS[i]);android.graphics.drawable.GradientDrawable background=new android.graphics.drawable.GradientDrawable();background.setColor(chosen?(ProfileStatus.COLORS[i]&0xffffff)|0x33000000:0xff201c2c);background.setCornerRadius(NativeSheet.dp(c,12));background.setStroke(NativeSheet.dp(c,1),chosen?ProfileStatus.COLORS[i]:0xff3b3349);option.setBackground(background);}};LinearLayout statusRow=null;for(int i=0;i<statusButtons.length;i++){if(i%2==0){statusRow=new LinearLayout(c);status.addView(statusRow);}final int choice=i;Button option=new Button(c);AppStyle.button(option,false);option.setTextSize(12);option.setMinWidth(0);option.setPadding(NativeSheet.dp(c,8),NativeSheet.dp(c,8),NativeSheet.dp(c,8),NativeSheet.dp(c,8));statusButtons[i]=option;LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,NativeSheet.dp(c,44),1);lp.setMargins(0,NativeSheet.dp(c,3),NativeSheet.dp(c,5),NativeSheet.dp(c,3));statusRow.addView(option,lp);option.setOnClickListener(v->{selectedStatus[0]=choice;paint.run();});}if(statusButtons.length%2==1)statusRow.addView(new android.view.View(c),new LinearLayout.LayoutParams(0,1,1));paint.run();infoPanel.addView(status);Button title=new Button(c);title.setText("Escolher título desbloqueado");AppStyle.button(title,false);infoPanel.addView(title);title.setOnClickListener(v->TitleSelectionDialog.show(c,profile,saved));TextView state=NativeSheet.text(c,"",13,0xffb7a6ff);body.addView(state);Button save=new Button(c);save.setText("Salvar alterações");AppStyle.button(save,true);body.addView(save);
  save.setOnClickListener(v->{String n=name.getText().toString(),b=bio.getText().toString(),s=ProfileInput.STATUS[selectedStatus[0]];try{ProfileInput.validate(n,b,s);}catch(IllegalArgumentException e){state.setText(e.getMessage());return;}sheet.busy(true);name.setEnabled(false);bio.setEnabled(false);for(Button option:statusButtons)option.setEnabled(false);save.setEnabled(false);state.setText("Salvando…");new AccountRepository(c).updateProfile(n,b,s,(rows,error)->{sheet.busy(false);if(!sheet.dialog.isShowing())return;if(error!=null){state.setText(error+" Feche e atualize o perfil antes de tentar novamente.");return;}if(c instanceof MainActivity)((MainActivity)c).refreshPresence();sheet.dialog.dismiss();saved.run();});});sheet.show();
 }
}
